const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const start = new Date(end);
start.setUTCDate(start.getUTCDate() - 7);
const toIso = (d) => d.toISOString().replace(/\.\d{3}Z$/, 'Z');
const owner = ($env.GITHUB_OWNER || 'mamenesia').trim();
const repo = ($env.GITHUB_REPO || 'claude-builders-bounty').trim();
const model = ($env.ANTHROPIC_MODEL || 'claude-sonnet-4-20250514').trim();
return [{
  json: {
    owner,
    repo,
    model,
    since: toIso(start),
    until: toIso(end),
    weekLabel: `${toIso(start).slice(0, 10)} → ${toIso(end).slice(0, 10)}`
  }
}];

const meta = $('Compute Week Window').first().json;
const commitsRaw = $('GitHub Commits').all().map(i => i.json).flat();
const prsRaw = $('GitHub Pull Requests').all().map(i => i.json).flat();
const commits = (Array.isArray(commitsRaw) ? commitsRaw : [commitsRaw]).filter(c => c && c.sha);
const prs = (Array.isArray(prsRaw) ? prsRaw : [prsRaw]).filter(p => p && p.number);
const sinceMs = Date.parse(meta.since);
const untilMs = Date.parse(meta.until);
const merged = prs.filter(p => p.merged_at && Date.parse(p.merged_at) >= sinceMs && Date.parse(p.merged_at) < untilMs);
const authors = {};
for (const c of commits) {
  const a = c.author?.login || c.commit?.author?.name || 'unknown';
  authors[a] = (authors[a] || 0) + 1;
}
const topAuthors = Object.entries(authors).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([login, count]) => ({ login, count }));
const commitLines = commits.slice(0, 40).map(c => `- ${c.sha.slice(0,7)} ${c.commit?.message?.split('\n')[0] || ''} (@${c.author?.login || 'unknown'})`);
const prLines = merged.slice(0, 20).map(p => `- #${p.number} ${p.title} (@${p.user?.login || 'unknown'})`);
const digest = [
  `Repository: ${meta.owner}/${meta.repo}`,
  `Window: ${meta.weekLabel}`,
  `Commits: ${commits.length}`,
  `Merged PRs: ${merged.length}`,
  '',
  'Top authors:',
  ...topAuthors.map(a => `- ${a.login}: ${a.count}`),
  '',
  'Recent commits:',
  ...(commitLines.length ? commitLines : ['- (none)']),
  '',
  'Merged PRs:',
  ...(prLines.length ? prLines : ['- (none)'])
].join('\n');
return [{
  json: {
    ...meta,
    commitCount: commits.length,
    mergedPrCount: merged.length,
    topAuthors,
    digest,
    prompt: `You are an engineering manager writing a crisp weekly development summary.\n\nUsing ONLY the data below, produce Markdown with these sections:\n1. Executive summary (3-5 sentences)\n2. Highlights (bullets)\n3. Key merged PRs\n4. Risks / follow-ups\n5. Suggested focus for next week\n\nBe specific. Do not invent commits or PRs.\n\nDATA:\n${digest}`
  }
}];

const meta = $('Build Claude Prompt').first().json;
const claude = $input.first().json;
const text = Array.isArray(claude.content)
  ? claude.content.filter(p => p.type === 'text').map(p => p.text).join('\n')
  : (claude.error?.message ? `Claude error: ${claude.error.message}` : JSON.stringify(claude).slice(0, 2000));
const md = [`# Weekly Dev Summary — ${meta.owner}/${meta.repo}`, '', `**Window:** ${meta.weekLabel}`, `**Commits:** ${meta.commitCount} · **Merged PRs:** ${meta.mergedPrCount}`, '', text].join('\n');
return [{
  json: {
    ...meta,
    summaryMarkdown: md,
    slackText: md.slice(0, 3500),
    emailSubject: `Weekly Dev Summary: ${meta.owner}/${meta.repo} (${meta.weekLabel})`
  }
}];
